Translate the following GNU C++0x code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++0x code you have to translate:
<original_code>
#include <iostream>
#include <string>
#include <cstdlib>
#include <vector>
#include <cmath>
using namespace std;

typedef long long llong;
#define sz(c) (int)(c).size()

llong gcd(llong a, llong b) {
    while( b )
        a%=b, swap(a,b);
    return a;
}

int main() {

    llong x, y, n; cin >> x >> y >> n;

    llong ansA, ansB;
    double dif = 1e12;
    for(llong b = 1; b <= n; b++) {
        llong l = 0, r = 100*1000;  
        llong a = 0;
        while( l <= r ) {
            llong mid = (l+r)>>1;
            if( mid*y <= x*b )
                a = mid, l = mid+1;
            else
                r = mid-1;
        }
        l = 0, r = 100*1000;
        llong aa = 0, bb = b;
        while( l <= r ) {
            llong mid = (l+r)>>1;
            if( mid*y < x*b )
                l = mid+1;
            else
                aa = mid, r = mid-1;
        }
        double curDif2 = abs(double(aa)/double(bb) - double(x)/double(y));
        double curDif1 = abs(double(a)/double(b) - double(x)/double(y));
       // cout << aa << "/" << bb << " " << curDif1 << "\n";
       // cout << a << "/" << b << " " << curDif2 << "\n";
       // cout << "\n";
        if( curDif2 + 1e-8 < curDif1) 
            a = aa, b = bb, curDif1 = curDif2;
        llong curGcd = gcd(a,b);
        if( curDif1 < dif )
            ansA = a/curGcd, ansB = b/curGcd, dif = curDif1;
    }

    cout << ansA << "/" << ansB;

    return 0;
}
